// --- configuration -------------------------------------------------
// Single configuration source for the whole workflow: base URL of the
// FastAPI service (no trailing slash, no /leads) AND the lead
// qualification threshold (integer 0-100). Override them with the
// LEAD_API_BASE_URL / LEAD_QUALIFIED_THRESHOLD environment variables of
// the n8n process. n8n 2.x blocks $env in expressions and Code nodes by
// default (N8N_BLOCK_ENV_ACCESS_IN_NODE), so each lookup is probed
// defensively and falls back to the documented defaults below. The
// *Source fields record which source was used and are visible in every
// execution; downstream nodes read this configuration from this node's
// output with $('Prepare Lead Payload') - the values are never repeated
// in another node.
const DEFAULT_API_BASE_URL = 'http://localhost:8000';
// Initial business rule, NOT an empirically validated sales threshold:
// the heuristic scorer starts at a baseline of 45; representative leads
// score 12-35 (junk), 63 (corporate inbound without an intent keyword)
// and 77-100 (explicit buying intent), so 70 sits in the observed 63-77
// gap and requires net positive signal above baseline. Tune it with
// LEAD_QUALIFIED_THRESHOLD (0-100).
const DEFAULT_QUALIFIED_THRESHOLD = 70;

let apiBaseUrl = DEFAULT_API_BASE_URL;
let apiBaseUrlSource = 'workflow-default';
try {
  const fromEnv = $env.LEAD_API_BASE_URL;
  if (fromEnv) {
    apiBaseUrl = String(fromEnv).replace(/\/+$/, '');
    apiBaseUrlSource = 'environment';
  }
} catch (err) {
  // $env denied (N8N_BLOCK_ENV_ACCESS_IN_NODE) or unavailable.
  apiBaseUrlSource = 'workflow-default (n8n blocks $env access)';
}

let qualifiedThreshold = DEFAULT_QUALIFIED_THRESHOLD;
let thresholdSource = 'workflow-default';
try {
  const fromEnv = $env.LEAD_QUALIFIED_THRESHOLD;
  if (fromEnv !== undefined && fromEnv !== null && String(fromEnv).trim() !== '') {
    const parsed = Number(fromEnv);
    if (Number.isFinite(parsed) && parsed >= 0 && parsed <= 100) {
      qualifiedThreshold = parsed;
      thresholdSource = 'environment';
    } else {
      thresholdSource = 'workflow-default (invalid LEAD_QUALIFIED_THRESHOLD)';
    }
  }
} catch (err) {
  thresholdSource = 'workflow-default (n8n blocks $env access)';
}

// --- payload mapping ------------------------------------------------
// FastAPI owns validation, persistence, duplicate detection and scoring.
// This node only copies the documented contract fields out of the webhook
// body and drops everything else - no validation rules are re-implemented.
const body = $input.first().json.body || {};

const lead = {
  name: body.name ?? null,
  email: body.email ?? null,
  company: body.company ?? null,
  message: body.message ?? null,
  source: body.source || 'n8n-webhook',
  external_id: body.external_id ?? null,
};

return [{
  json: {
    lead,
    apiLeadsUrl: `${apiBaseUrl}/leads`,
    apiBaseUrlSource,
    qualifiedThreshold,
    thresholdSource,
  },
}];

// Attach AI insights for the lead THIS execution created (fail-open).
// attachAiInsights is a verbatim copy of n8n/attach-ai-insights.js; the test
// suite fails if the two drift apart. The lead id is taken from this
// execution's "Create Lead in FastAPI" response, never from another node.
function attachAiInsights(created, insightsHttp) {
  created = created && typeof created === "object" ? created : {};
  insightsHttp = insightsHttp && typeof insightsHttp === "object" ? insightsHttp : {};
  const createdBody = created.body && typeof created.body === "object" ? created.body : {};
  const leadId = Number.isInteger(createdBody.lead_id) ? createdBody.lead_id : null;

  const FIELDS = ["summary", "intent_category", "urgency", "recommended_next_action", "reason"];
  const CATEGORIES = ["quote_request", "consultation", "support", "partnership", "other"];
  const URGENCIES = ["low", "medium", "high"];
  const NON_COMPLETED = ["disabled", "failed", "pending"];

  const unavailable = (error) => ({ status: "unavailable", lead_id: leadId, insights: null, error });

  let aiInsights;
  const body = insightsHttp.body && typeof insightsHttp.body === "object" ? insightsHttp.body : null;
  if (leadId === null) {
    aiInsights = unavailable("missing_created_lead_id");
  } else if (typeof insightsHttp.statusCode !== "number") {
    // n8n HTTP node error output (timeout, DNS, connection refused, ...)
    aiInsights = unavailable("insights_request_failed");
  } else if (insightsHttp.statusCode !== 200 || !body) {
    aiInsights = unavailable("insights_http_" + insightsHttp.statusCode);
  } else if (body.lead_id !== leadId) {
    aiInsights = unavailable("lead_id_mismatch");
  } else if (body.status === "completed") {
    const raw = body.insights && typeof body.insights === "object" ? body.insights : {};
    const valid =
      FIELDS.every((f) => typeof raw[f] === "string" && raw[f].trim() !== "") &&
      CATEGORIES.includes(raw.intent_category) &&
      URGENCIES.includes(raw.urgency);
    if (valid) {
      const insights = {};
      FIELDS.forEach((f) => { insights[f] = raw[f]; });
      aiInsights = {
        status: "completed",
        lead_id: leadId,
        insights,
        model: typeof body.model === "string" ? body.model : null,
        error: null,
      };
    } else {
      aiInsights = unavailable("invalid_insights");
    }
  } else if (NON_COMPLETED.includes(body.status)) {
    aiInsights = {
      status: body.status,
      lead_id: leadId,
      insights: null,
      error: typeof body.error === "string" ? body.error : null,
    };
  } else {
    aiInsights = unavailable("unexpected_insights_status");
  }

  // Keep the create-lead response shape ({statusCode, body, ...}) intact so
  // the existing downstream nodes read exactly what they read before.
  return Object.assign({}, created, { aiInsights });
}

const created = $('Create Lead in FastAPI').first().json;
return [{ json: attachAiInsights(created, $input.first().json) }];
